import {icon} from './app.mjs';
import {initPayments,paymentPreview} from './payment-ui.mjs';
import {initWorkspace} from './workspace-ui.mjs';
import {createWorkspaceStore,validMonth,WORKSPACE_CONFLICT} from './workspace-data.mjs';
import {correctPaymentDate} from './payments.mjs';
import {CURRENCIES,CATEGORIES,BANK_RULES,localDate,validDate,demoTransactions,parseBatch,summarize,receiptSuggestion,fingerprint,transactionKeys} from './domain.mjs';
const $=id=>document.getElementById(id);
const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c=state.currency)=>new Intl.NumberFormat('en-US',{style:'currency',currency:c,maximumFractionDigits:['KRW','VND'].includes(c)?0:2}).format(n);
const option=(value,selected,label=value)=>`<option value="${escape(value)}" ${value===selected?'selected':''}>${escape(label)}</option>`;
const colors={'Food & drinks':'#a9cb7b','Groceries':'#41664d','Shopping':'#dcb57f','Transport':'#9abbbb','Bills & home':'#c5d6ab','Health':'#d69d9d','Entertainment':'#9b9bbc','Travel':'#7eafaa','Other':'#c2c8bb'};
const categoryIcons={'Food & drinks':'coffee','Groceries':'shop','Shopping':'shop','Transport':'car','Bills & home':'home','Health':'heart','Entertainment':'play'};
const KEY='penny.local.v1';
let paymentPage=null,workspaceUI=null;
let state={transactions:demoTransactions(),rules:structuredClone(BANK_RULES),demo:true,currency:'KRW',month:localDate().slice(0,7),bank:'all',view:'overview',budgets:{}};
const workspaceStore=createWorkspaceStore({getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},KEY,navigator.locks);
if(workspaceStore.data)state={...state,...workspaceStore.data};
const preferencesKey='penny.preferences.v1';
try{const prefs=JSON.parse(localStorage.getItem(preferencesKey));if(prefs&&validMonth(prefs.month)&&CURRENCIES.includes(prefs.currency))Object.assign(state,{month:prefs.month,currency:prefs.currency});}catch{}
function persistPreferences(){try{localStorage.setItem(preferencesKey,JSON.stringify({month:state.month,currency:state.currency}));}catch{/* Filter choices can remain session-only. */}}
let storageError=workspaceStore.error||'';
async function persist(){try{await workspaceStore.saveLocked(state);storageError='';persistPreferences();}catch(err){storageError=err.message+' Changes are temporary. Use Backup & restore before closing this tab.';}storageNotice();return !storageError;}
async function restoreWorkspace(data){const restored=await workspaceStore.saveLocked(data,{restore:true});state={...state,...restored,bank:'all'};storageError='';persistPreferences();paymentPage?.afterImport();render();}
function storageNotice(){$('storage-warning').textContent=storageError;$('storage-warning').classList.toggle('hidden',!storageError);}
window.addEventListener('storage',event=>{if(event.key===KEY||event.key===null){try{if(workspaceStore.isStale()){storageError=WORKSPACE_CONFLICT;storageNotice();}}catch{}}});
let toastTimer;
function toast(text){$('toast').textContent=storageError?'Changes are temporary. Use Backup & restore to protect your records.':text;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4200);}
function currentSummary(){return summarize(state.transactions,{month:state.month,currency:state.currency,bank:state.bank});}
function visibleTransactions(){let rows=currentSummary().selected;const term=$('search').value.toLowerCase();const cat=$('category-filter').value;if(state.view==='transactions'){rows=rows.filter(t=>(cat==='all'||t.category===cat)&&($('review-filter')?.value!=='review'||t.warnings?.length)&&(!term||(t.merchant+' '+t.raw+' '+t.bank).toLowerCase().includes(term)));}return [...rows].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));}
function render(){
  $('demo-banner').classList.toggle('hidden',!state.demo||state.view==='incoming');$('nav-count').textContent=state.transactions.length;
  $('month-filter').value=state.month;
  const banks=[...new Set(state.transactions.map(t=>t.bank))].sort();if(state.bank!=='all'&&!banks.includes(state.bank))state.bank='all';
  $('bank-filter').innerHTML=option('all',state.bank,'All banks')+banks.map(b=>option(b,state.bank)).join('');
  $('currency-filter').innerHTML=CURRENCIES.filter(c=>['KRW','VND'].includes(c)||state.transactions.some(t=>t.currency===c)).map(c=>option(c,state.currency,c==='KRW'?'₩ KRW':c==='VND'?'₫ VND':c)).join('');
  const s=currentSummary();$('spending-value').textContent=money(s.spending);$('income-value').textContent=money(s.moneyIn);$('balance-value').textContent=money(s.net);$('spending-detail').textContent=`${s.expenses.length} expenses · ${state.currency}`;$('income-detail').textContent=`${s.selected.filter(t=>['income','refund'].includes(t.type)).length} income & refund transactions`;
  const days=new Date(Number(state.month.slice(0,4)),Number(state.month.slice(5,7)),0).getDate();const max=Math.max(...Object.values(s.days),1);
  $('spending-chart').innerHTML=`<span class="chart-scale">${money(max===1?0:max)}</span><div class="chart-grid" role="img" aria-label="Daily spending chart. Monthly total ${escape(money(s.spending))}">${Array.from({length:days},(_,i)=>{const amount=s.days[i+1]||0;return `<div class="chart-bar ${amount===max?'peak':''}" style="height:${amount?Math.max(amount/max*100,3):2}%" title="${state.month}-${String(i+1).padStart(2,'0')}: ${escape(money(amount))}"></div>`;}).join('')}</div><div class="chart-labels"><span>01</span><span>05</span><span>10</span><span>15</span><span>20</span><span>25</span><span>${days}</span></div>`;
  const cats=Object.entries(s.categories).sort((a,b)=>b[1]-a[1]);const shown=cats.length>5?[...cats.slice(0,4),['Other categories',cats.slice(4).reduce((v,c)=>v+c[1],0)]]:cats;
  let cursor=0;const stops=shown.map(([name,value])=>{const start=cursor;cursor+=value/s.spending*100;return `${colors[name]||'#c2c8bb'} ${start}% ${cursor}%`;});
  $('category-donut').style.background=stops.length?`conic-gradient(${stops.join(',')})`:'#edf1e9';$('category-donut').setAttribute('aria-label','Category breakdown');$('category-count').textContent=cats.length;
  $('category-list').innerHTML=shown.length?shown.map(([name,value])=>`<div class="category-row"><span class="category-name"><span class="category-dot" style="background:${colors[name]||'#c2c8bb'}"></span>${escape(name)}</span><strong>${escape(money(value))}<small>${Math.round(value/s.spending*100)}%</small></strong></div>`).join(''):'<p class="muted">No expenses this month.</p>';
  const rows=visibleTransactions();const subset=state.view==='overview'?rows.slice(0,5):rows;
  $('transaction-rows').innerHTML=subset.map(t=>`<tr><td><div class="merchant"><span class="merchant-icon">${icon(categoryIcons[t.category]||'wallet')}</span><div>${escape(t.merchant)}${t.warnings?.length?'<span class="review-badge">Review</span>':''}<small>${t.source==='receipt'?'Receipt scan':t.source==='manual'?'Manual entry':'Bank SMS'} · ${escape(t.bank)}</small></div></div></td><td>${new Date(t.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'2-digit'})}</td><td><span class="tag ${t.type}">${escape(t.category)}</span></td><td>${escape(t.bank)}</td><td class="align-right amount ${t.type}">${['income','refund'].includes(t.type)?'+':t.type==='expense'?'−':''}${escape(money(t.amount,t.currency))}</td><td><button class="edit-button" data-edit="${escape(t.id)}" aria-label="Edit ${escape(t.merchant)}">⋯</button></td></tr>`).join('');
  $('empty-state').classList.toggle('hidden',rows.length>0);$('transaction-count').textContent=`${subset.length} of ${rows.length} transactions · ${state.currency}`;
  $('empty-state').querySelector('h3').textContent=state.transactions.length?'No matching transactions.':'A clean slate.';
  $('empty-state').querySelector('p').textContent=state.transactions.length?'Try a different month or clear the search, category, and review filters.':'Add a transaction, scan a receipt, or import bank messages to get started.';
  $('transactions-heading').textContent=state.view==='transactions'?'All transactions':'Recent transactions';$('transaction-tools').classList.toggle('hidden',state.view!=='transactions');$('view-all').classList.toggle('hidden',state.view!=='overview');
  $('overview-view').classList.toggle('hidden',state.view!=='overview');$('transactions-view').classList.toggle('hidden',!['overview','transactions'].includes(state.view));$('rules-view').classList.toggle('hidden',state.view!=='rules');$('filters').classList.toggle('hidden',['rules','incoming'].includes(state.view));
  const titles={overview:['Overview','Your money, made clear.','A simple view of where your money goes.'],transactions:['Transactions','Every transaction, in view.','Review, categorize, and keep your records in order.'],rules:['Bank rules','Recognize your banks.','Korean and Vietnamese banks, all in one place.'],incoming:['Incoming payments','Every payment, down to the moment.','Track money received from buyers, friends, and other people.']};const title=titles[state.view];$('breadcrumb').textContent=title[0];$('page-title').textContent=title[1];$('page-description').textContent=title[2];document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});
  $('rules-list').innerHTML=state.rules.map((r,i)=>`<div class="rule-row"><span class="merchant-icon">${icon('bank')}</span><div><strong>${escape(r.name)}</strong><p>${escape(r.keywords.join(' · '))}</p></div><button class="icon-button" data-delete-rule="${i}" aria-label="Remove ${escape(r.name)} rule">×</button></div>`).join('');storageNotice();
  paymentPage?.render();
  workspaceUI?.render();
}
function setView(view){const previous=state.view;state.view=['overview','transactions','rules','incoming'].includes(view)?view:'overview';if(location.hash!=='#'+state.view)history.replaceState(null,'','#'+state.view);render();if(previous!==state.view)window.scrollTo({top:0,behavior:'instant'});}
$('category-filter').innerHTML=option('all','all','All categories')+CATEGORIES.map(c=>option(c)).join('');
$('edit-category').innerHTML=CATEGORIES.map(c=>option(c)).join('');$('edit-currency').innerHTML=CURRENCIES.map(c=>option(c)).join('');
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('view-all').onclick=()=>setView('transactions');
$('month-filter').onchange=e=>{if(validMonth(e.target.value)){state.month=e.target.value;persistPreferences();render();}};
$('bank-filter').onchange=e=>{state.bank=e.target.value;render();};$('currency-filter').onchange=e=>{state.currency=e.target.value;persistPreferences();render();};$('search').oninput=render;$('category-filter').onchange=render;
function openImport(){resetImport();$('import-date').value=localDate();$('import-currency').value=state.currency;$('import-dialog').showModal();}
$('import-button').onclick=openImport;$('empty-import').onclick=openImport;$('start-fresh').onclick=()=>$('confirm-dialog').showModal();
$('confirm-clear').onclick=async()=>{state.transactions=[];state.demo=false;state.bank='all';await persist();render();$('confirm-dialog').close();openImport();};
let importedFile=null,staged=null;
function resetImport(){$('import-input-step').classList.remove('hidden');$('import-review-step').classList.add('hidden');$('import-review-step').innerHTML='';$('parse-button').classList.remove('hidden');$('save-import').classList.add('hidden');$('import-back').classList.add('hidden');$('import-error').textContent='';staged=null;}
$('import-back').onclick=resetImport;
$('sms-input').oninput=()=>{importedFile=null;$('file-name').textContent='';$('sms-file').value='';};
const samples=()=>`[신한카드] 승인\n김*민님\n${localDate()} 12:35\n12,500원\n스타벅스 강남\n일시불\n\nVCB: GD -185,000 VND tai Highlands Coffee ngay ${localDate()}. So du: 8,500,000 VND.\n\n[KB국민은행] 입금 3,200,000원 ${localDate()} 급여 잔액 4,800,000원\n\nVietcombank: Ma OTP 123456. Khong chia se ma nay.`;
$('example-button').onclick=()=>{$('sms-input').value=samples();importedFile=null;$('file-name').textContent='';};
$('sms-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){$('import-error').textContent='Choose a file smaller than 5 MB.';return;}try{const text=await file.text();let messages;if(file.name.toLowerCase().endsWith('.json')){const data=JSON.parse(text);messages=Array.isArray(data)?data:data.messages;if(!Array.isArray(messages)||!messages.every(x=>typeof x==='string'||x&&typeof x==='object'&&['body','text','message'].some(k=>typeof x[k]==='string')))throw new Error('JSON must contain an array of messages with body, sender, and optional date fields.');}else if(file.name.toLowerCase().endsWith('.xml')){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw new Error('This XML file could not be read.');messages=[...doc.querySelectorAll('sms')].map(x=>({body:x.getAttribute('body')||'',sender:x.getAttribute('address')||'',date:x.getAttribute('date')||''}));if(!messages.length)throw new Error('No SMS records found in this XML.');}else messages=text.split(/\r?\n\s*\r?\n/);if(messages.length>5000)throw new Error('Import up to 5,000 messages at a time.');importedFile=messages;$('sms-input').value=messages.map(m=>typeof m==='string'?m:m.body??m.text??m.message).join('\n\n');$('file-name').textContent=`${file.name} · ${messages.length} messages`;$('import-error').textContent='';}catch(err){$('import-error').textContent=err.message;importedFile=null;}};
$('parse-button').onclick=()=>{try{if(!validDate($('import-date').value))throw new Error('Choose a valid fallback date.');const messages=importedFile||$('sms-input').value.split(/\r?\n\s*\r?\n/);if(!messages.some(m=>typeof m==='string'?m.trim():true))throw new Error('Paste messages or choose an SMS file first.');staged=parseBatch(messages,{currency:$('import-currency').value,date:$('import-date').value,rules:state.rules},state.demo?[]:state.transactions);renderReview();}catch(err){$('import-error').textContent=err.message;}};
function renderReview(){$('import-input-step').classList.add('hidden');$('import-review-step').classList.remove('hidden');$('parse-button').classList.add('hidden');$('save-import').classList.remove('hidden');$('import-back').classList.remove('hidden');$('import-error').textContent='';$('save-import').disabled=!staged.transactions.length;
  $('import-review-step').innerHTML=`<div class="review-summary"><strong>${staged.transactions.length} transactions found</strong><p>${staged.skipped.length} messages skipped.${state.demo?' Saving replaces the demo transactions.':''}</p></div>${staged.transactions.map((t,i)=>`<div class="review-row" data-review="${i}"><div class="review-head"><label><input type="checkbox" data-field="include" checked> ${escape(t.bank)}</label><strong>${escape(money(t.amount,t.currency))}</strong></div><div class="review-fields"><label>Merchant<input data-field="merchant" value="${escape(t.merchant)}" maxlength="100"></label><label>Amount<input data-field="amount" type="number" min="1" step="1" value="${t.amount}"></label><label>Currency<select data-field="currency">${CURRENCIES.map(c=>option(c,t.currency)).join('')}</select></label><label>Date<input data-field="date" type="date" value="${t.date}"></label><label>Category<select data-field="category">${CATEGORIES.map(c=>option(c,t.category)).join('')}</select></label><label>Type<select data-field="type">${['expense','income','refund','transfer'].map(c=>option(c,t.type)).join('')}</select></label><label>Bank<input data-field="bank" value="${escape(t.bank)}" maxlength="60"></label></div>${paymentPreview(t,escape)}${t.warnings.length?`<p class="review-warning">${escape(t.warnings.join(' · '))}</p>`:''}<details><summary>View SMS</summary><p class="raw-message">${escape(t.raw)}</p></details></div>`).join('')}${staged.skipped.length?`<details><summary>${staged.skipped.length} skipped messages</summary><ul class="skipped-list">${staged.skipped.map(s=>`<li><strong>${escape(s.reason)}</strong> — ${escape(s.raw.slice(0,100))}</li>`).join('')}</ul></details>`:''}`;}
function validTransaction(t){return t.merchant.trim()&&t.bank.trim()&&validDate(t.date)&&Number.isFinite(t.amount)&&t.amount>0&&t.amount<=1e12&&(!['KRW','VND'].includes(t.currency)||Number.isInteger(t.amount));}
async function commitTransactions(rows){if(state.demo){state.transactions=[];state.demo=false;}state.transactions.push(...rows);state.month=[...rows].sort((a,b)=>b.date.localeCompare(a.date))[0].date.slice(0,7);state.currency=rows[0].currency;state.bank='all';await persist();paymentPage?.afterImport();render();}
$('save-import').onclick=async()=>{const rows=[];for(const el of document.querySelectorAll('[data-review]')){if(!el.querySelector('[data-field="include"]').checked)continue;const original=staged.transactions[Number(el.dataset.review)];const t={...original,id:crypto.randomUUID(),warnings:[]};for(const field of ['merchant','amount','currency','date','category','type','bank'])t[field]=field==='amount'?Number(el.querySelector(`[data-field="${field}"]`).value):el.querySelector(`[data-field="${field}"]`).value.trim();if(!validTransaction(t)){$('import-error').textContent='Check each selected merchant, bank, date, and amount. Won and dong must be whole numbers.';return;}if(t.type==='transfer')t.category='Transfer';const corrected={...t,date:original.date};correctPaymentDate(corrected,t.date);t.transactionTime=corrected.transactionTime;t.incomingTransfer=t.type==='income';if(t.incomingTransfer&&t.merchant!==original.merchant)t.payer=t.merchant;t.fingerprint=original.fingerprint||fingerprint(t);rows.push(t);}if(!rows.length){$('import-error').textContent='Select at least one transaction.';return;}const seen=new Set((state.demo?[]:state.transactions).flatMap(transactionKeys));const unique=rows.filter(t=>{if(seen.has(t.fingerprint))return false;seen.add(t.fingerprint);return true;});if(!unique.length){$('import-error').textContent='These transactions have already been imported.';return;}await commitTransactions(unique);$('import-dialog').close();$('sms-input').value='';importedFile=null;toast(`Saved ${unique.length} transactions on this device.`);};
$('transaction-rows').onclick=e=>{const b=e.target.closest('[data-edit]');if(!b)return;const t=state.transactions.find(t=>t.id===b.dataset.edit);for(const field of ['id','merchant','amount','currency','date','type','category','bank'])$('edit-'+field).value=t[field];$('edit-raw').textContent=t.raw;$('edit-error').textContent='';$('edit-dialog').showModal();};
$('edit-form').onsubmit=async e=>{e.preventDefault();const t=state.transactions.find(t=>t.id===$('edit-id').value);const next={...t,warnings:[]};for(const field of ['merchant','amount','currency','date','type','category','bank'])next[field]=field==='amount'?Number($('edit-'+field).value):$('edit-'+field).value.trim();if(!validTransaction(next)){$('edit-error').textContent='Check the amount, date, merchant, and bank. Won and dong must be whole numbers.';return;}if(next.type==='transfer')next.category='Transfer';const corrected={...next,date:t.date};correctPaymentDate(corrected,next.date);next.transactionTime=corrected.transactionTime;next.incomingTransfer=next.type==='income'&&next.source==='sms';next.ownAccount=next.type==='transfer'&&t.ownAccount;if(next.incomingTransfer&&next.merchant!==t.merchant)next.payer=next.merchant;Object.assign(t,next);await persist();render();$('edit-dialog').close();toast('Transaction updated.');};
$('delete-transaction').onclick=async()=>{const row=state.transactions.find(t=>t.id===$('edit-id').value);if(!row)return;workspaceUI.rememberDeleted(row);state.transactions=state.transactions.filter(t=>t.id!==row.id);await persist();render();$('edit-dialog').close();toast('Transaction removed. You can undo this deletion.');};
$('add-rule').onclick=()=>{$('rule-form').reset();$('rule-dialog').showModal();};
$('rule-form').onsubmit=async e=>{e.preventDefault();const name=$('rule-name').value.trim(),keywords=$('rule-keywords').value.split(',').map(x=>x.trim()).filter(Boolean);if(!name||!keywords.length)return;const existing=state.rules.find(r=>r.name.toLowerCase()===name.toLowerCase());if(existing)existing.keywords=[...new Set([...keywords,...existing.keywords])];else state.rules.unshift({name,keywords});await persist();render();$('rule-dialog').close();toast('Bank rule saved for future imports.');};
$('rules-list').onclick=async e=>{const b=e.target.closest('[data-delete-rule]');if(!b)return;state.rules.splice(Number(b.dataset.deleteRule),1);await persist();render();toast('Bank rule removed.');};
$('export-button').onclick=()=>{const fields=['date','merchant','bank','type','category','amount','currency','source'];const cell=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"';const csv='\uFEFF'+fields.join(',')+'\r\n'+visibleTransactions().map(t=>fields.map(f=>cell(t[f])).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`penny-${state.month}-${state.currency}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported the filtered transactions.');};
// Receipt photos are processed in a browser worker. Only OCR model files are fetched.
let receiptFile=null,receiptDraft=null,previewUrl=null,ocrWorker=null;
const scanDialog=document.createElement('dialog');scanDialog.id='scan-dialog';scanDialog.setAttribute('aria-labelledby','scan-title');scanDialog.innerHTML=`<div class="dialog-heading"><div><p class="eyebrow">SNAP. CHECK. SAVE.</p><h2 id="scan-title">Scan a receipt</h2></div><button class="icon-button" id="close-scan" aria-label="Close receipt scanner">×</button></div><p class="dialog-description">Choose a receipt or payment screenshot. We’ll suggest the merchant and amount. Review the details before adding them.</p><div class="scan-controls"><label class="upload-zone">${icon('inbox')}<strong>Choose a photo</strong><span>JPG, PNG, or WebP · up to 12 MB</span><input id="receipt-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Choose receipt photo"></label><img id="receipt-preview" class="hidden" alt="Selected receipt preview"><label>Receipt language<select id="ocr-language"><option value="kor+eng">Korean + English</option><option value="vie+eng">Vietnamese + English</option></select></label><button id="run-ocr" class="button primary" disabled>Read receipt</button></div><p id="ocr-progress" role="status" class="helper">The first scan downloads the OCR engine and language files. The photo is processed on your device.</p><div id="ocr-review" class="hidden"><div class="review-summary"><strong>Check the suggested details</strong><p>OCR can misread numbers. Compare with your receipt.</p></div><form id="receipt-form"><div class="form-grid"><label>Merchant / spending name<input id="receipt-merchant" required maxlength="100"></label><label>Amount<input id="receipt-amount" type="number" min="1" step="1" required></label><label>Currency<select id="receipt-currency">${CURRENCIES.map(c=>option(c)).join('')}</select></label><label>Date<input id="receipt-date" type="date" required></label><label>Category<select id="receipt-category">${CATEGORIES.filter(c=>!['Income','Refund','Transfer'].includes(c)).map(c=>option(c)).join('')}</select></label><label>Paid with<input id="receipt-bank" value="Cash / receipt" required maxlength="60"></label></div><p id="receipt-alternatives" class="helper"></p><details><summary>Recognized text</summary><textarea id="ocr-text" rows="6" aria-label="Recognized receipt text"></textarea><button id="reparse-receipt" type="button" class="text-button">Update suggestions from text</button></details><p class="helper">Already imported the SMS for this purchase? Save only one record to avoid counting it twice.${state.demo?' Saving will replace the demo data.':''}</p><div class="dialog-actions"><button class="button primary" type="submit">Save expense</button></div></form></div><details class="manual-ocr"><summary>Enter details or paste receipt text instead</summary><textarea id="manual-receipt-text" rows="4" placeholder="Paste recognized text here, or leave blank to enter the expense yourself." aria-label="Receipt text to analyze"></textarea><button id="manual-receipt" class="text-button">Suggest details / enter manually</button></details><p id="scan-error" class="error" role="alert"></p>`;document.body.append(scanDialog);
const scanButton=document.createElement('button');scanButton.id='scan-button';scanButton.className='button secondary';scanButton.innerHTML=icon('inbox')+' Scan receipt';$('import-button').before(scanButton);
const actions=document.createElement('div');actions.className='heading-actions';scanButton.before(actions);actions.append(scanButton,$('import-button'));
const deleteData=document.createElement('button');deleteData.className='text-button';deleteData.textContent='Clear transactions';deleteData.onclick=()=>$('confirm-dialog').showModal();document.querySelector('.main-footer').append(deleteData);
scanButton.onclick=()=>{$('ocr-language').value=state.currency==='VND'?'vie+eng':'kor+eng';scanDialog.showModal();};$('close-scan').onclick=()=>scanDialog.close();
$('receipt-file').onchange=e=>{receiptFile=null;$('run-ocr').disabled=true;$('ocr-review').classList.add('hidden');$('scan-error').textContent='';const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){$('scan-error').textContent='Choose a JPG, PNG, or WebP smaller than 12 MB.';return;}receiptFile=file;if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(file);$('receipt-preview').src=previewUrl;$('receipt-preview').classList.remove('hidden');$('run-ocr').disabled=false;};
function showReceipt(text){receiptDraft=receiptSuggestion(text,{currency:$('ocr-language').value.startsWith('vie')?'VND':'KRW'});for(const field of ['merchant','amount','currency','date','category','bank'])$('receipt-'+field).value=receiptDraft[field];$('ocr-text').value=text;$('receipt-alternatives').textContent=receiptDraft.alternatives.length>1?'Amounts found: '+receiptDraft.alternatives.map(v=>money(v,receiptDraft.currency)).join(' · '):'';$('ocr-review').classList.remove('hidden');}
async function loadOcr(){if(globalThis.Tesseract)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');const fail=()=>{clearTimeout(timeout);s.remove();reject(new Error('OCR could not download. Check your connection, or enter the receipt details manually.'));};const timeout=setTimeout(fail,30000);s.src='https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/tesseract.min.js';s.onload=()=>{clearTimeout(timeout);resolve();};s.onerror=fail;document.head.append(s);});}
$('run-ocr').onclick=async()=>{if(!receiptFile)return;$('run-ocr').disabled=true;$('receipt-file').disabled=true;$('ocr-language').disabled=true;$('scan-error').textContent='';$('ocr-review').classList.add('hidden');$('ocr-progress').textContent='Loading the OCR engine…';let timer;try{await loadOcr();const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('OCR took too long. Try a smaller, clearer photo, or enter the details manually.')),120000);});await Promise.race([(async()=>{ocrWorker=await Tesseract.createWorker($('ocr-language').value,1,{workerPath:'https://cdn.jsdelivr.net/npm/tesseract.js@6.0.1/dist/worker.min.js',corePath:'https://cdn.jsdelivr.net/npm/tesseract.js-core@6.0.0',logger:m=>{$('ocr-progress').textContent=`${m.status.replaceAll('_',' ')}${typeof m.progress==='number'?' · '+Math.round(m.progress*100)+'%':''}`;}});const {data}=await ocrWorker.recognize(receiptFile);if(!data.text.trim())throw new Error('No readable text found. Try a brighter, straight-on photo.');showReceipt(data.text);$('ocr-progress').textContent='Scan complete. Review the amount and merchant below.';})(),timeout]);}catch(err){$('scan-error').textContent=err.message;$('ocr-progress').textContent='You can still enter the expense manually.';}finally{clearTimeout(timer);if(ocrWorker){await ocrWorker.terminate().catch(()=>{});ocrWorker=null;}$('run-ocr').disabled=false;$('receipt-file').disabled=false;$('ocr-language').disabled=false;}};
$('manual-receipt').onclick=()=>{showReceipt($('manual-receipt-text').value);$('scan-error').textContent='';};$('reparse-receipt').onclick=()=>showReceipt($('ocr-text').value);
$('receipt-form').onsubmit=async e=>{e.preventDefault();const t={...receiptDraft,id:crypto.randomUUID(),source:'receipt',type:'expense',warnings:[],raw:$('ocr-text').value};for(const field of ['merchant','amount','currency','date','category','bank'])t[field]=field==='amount'?Number($('receipt-'+field).value):$('receipt-'+field).value.trim();if(!validTransaction(t)){$('scan-error').textContent='Check the merchant, amount, currency, and date. Won and dong must be whole numbers.';return;}if(!t.raw)t.raw=`${t.merchant}|${t.amount}|${t.currency}`;t.fingerprint=fingerprint(t);const match=(state.demo?[]:state.transactions).some(x=>x.fingerprint===t.fingerprint);if(match){$('scan-error').textContent='This receipt has already been saved.';return;}await commitTransactions([t]);scanDialog.close();$('ocr-review').classList.add('hidden');$('receipt-file').value='';$('receipt-preview').classList.add('hidden');receiptFile=null;$('run-ocr').disabled=true;if(previewUrl)URL.revokeObjectURL(previewUrl);toast('Expense saved on this device.');};
